// Motor de estados sobre la hoja "Solicitudes". Una acción por fila por ejecución.
// Las notificaciones de solicitudes nuevas y cancelaciones ya salen al instante desde el
// sub-workflow; aquí solo se reintentan si el correo había fallado (bandera vacía).
// US-2-AC-3: la confirmación y el recordatorio dicen qué profesional asignó Erika
// (columna profesional_asignado; si está vacía, el que eligió el estudiante).
// US-5: las solicitudes PENDIENTE_VALIDACION también se avisan a la encargada.
// US-6: avisa al estudiante cada cambio de estado_pago que hace Erika (recibo enviado, pago validado,
//       comprobante rechazado) y NO confirma una cita que requiere pago hasta que el pago esté validado.
// US-7: avisa al estudiante cuando Salud Integral RECHAZA o CANCELA su solicitud (aviso_estado = POR_AVISAR,
//       lo pone el Apps Script de la hoja) y CIERRA solo las citas CONFIRMADAS que ya pasaron (estado CERRADA).
//       Las filas antiguas nunca tienen POR_AVISAR, así que no reciben avisos.
const AVISOS_PAGO = ['RECIBO_ENVIADO', 'PAGO_VALIDADO', 'COMPROBANTE_RECHAZADO'];
const HORAS_RECORDATORIO = 24;
const DURACION_MIN = 30;           // duración usada para el evento de calendario
const ZONA = 'America/Bogota';
const FINALES = ['RECHAZADA', 'CANCELADA', 'CERRADA'];
const MAX_CIERRES = 20;           // cierres automáticos por ejecución (cuida el límite de escrituras de Google)
let cierres = 0;
const ahora = DateTime.now().setZone(ZONA);

function parseFecha(f) {
  if (f === '' || f == null) return null;
  if (typeof f === 'number')
    return DateTime.fromObject({ year: 1899, month: 12, day: 30 }, { zone: ZONA }).plus({ days: Math.floor(f) });
  const s = String(f).trim();
  for (const fmt of ['dd/MM/yyyy', 'd/M/yyyy', 'yyyy-MM-dd']) {
    const d = DateTime.fromFormat(s, fmt, { zone: ZONA });
    if (d.isValid) return d;
  }
  return null;
}
function parseHora(h) {
  if (h === '' || h == null) return null;
  if (typeof h === 'number') { const m = Math.round(h * 1440); return { hour: Math.floor(m / 60) % 24, minute: m % 60 }; }
  const s = String(h).trim().toLowerCase().replace(/\s+/g, '').replace(/\./g, '');
  const m = s.match(/^(\d{1,2})(?::(\d{2}))?(am|pm)?$/);
  if (!m) return null;
  let hour = +m[1]; const minute = m[2] ? +m[2] : 0;
  if (m[3] === 'pm' && hour < 12) hour += 12;
  if (m[3] === 'am' && hour === 12) hour = 0;
  return { hour, minute };
}
const si = v => String(v ?? '').trim().toUpperCase() === 'SI';
const cap = s => s ? s.charAt(0).toUpperCase() + s.slice(1) : s;
const profesionalDe = r => String(r.profesional_asignado || r.profesional_solicitado || '').trim();

function enlaceCalendario(r, cita) {
  const fmt = d => d.toUTC().toFormat("yyyyLLdd'T'HHmmss'Z'");
  const p = {
    action: 'TEMPLATE',
    text: `Cita de ${cap(r.servicio)} · Salud Integral Unicauca`,
    dates: `${fmt(cita)}/${fmt(cita.plus({ minutes: DURACION_MIN }))}`,
    details: `Solicitud ${r.id}.${profesionalDe(r) ? ' Profesional: ' + profesionalDe(r) + '.' : ''} Si no puedes asistir, escribe CANCELAR a AVSI por WhatsApp.`,
    location: 'Salud Integral, Universidad del Cauca',
    ctz: ZONA,
  };
  return 'https://calendar.google.com/calendar/render?' +
    Object.entries(p).map(([k, v]) => k + '=' + encodeURIComponent(v).replace(/%2F/g, '/')).join('&');
}

const out = [];
for (const item of $input.all()) {
  const r = item.json;
  if (!r.id) continue;
  const estado = String(r.estado ?? '').trim().toUpperCase();
  let accion = null, cita = null;

  const estadoPago = String(r.estado_pago ?? '').trim().toUpperCase();
  const pagoPendiente = String(r.requiere_pago ?? '').trim().toUpperCase() === 'SI' && estadoPago !== 'PAGO_VALIDADO';
  if ((estado === 'PENDIENTE' || estado === 'PENDIENTE_VALIDACION') && !si(r.notificado_encargada)) accion = 'notificar_nueva';
  else if (estado === 'CANCELACION_SOLICITADA' && !si(r.notificado_cancelacion)) accion = 'notificar_cancelacion';
  else if ((estado === 'RECHAZADA' || estado === 'CANCELADA') && String(r.aviso_estado ?? '').trim().toUpperCase() === 'POR_AVISAR')
    accion = 'aviso_estado';
  // Agenda: el Apps Script detectó que Erika bloqueó (combinó celdas) la franja de la cita o del horario pedido.
  else if (String(r.aviso_bloqueo ?? '').trim().toUpperCase() === 'POR_AVISAR' && ['CONFIRMADA', 'PENDIENTE', 'PENDIENTE_VALIDACION'].includes(estado))
    accion = 'aviso_bloqueo';
  else if (!FINALES.includes(estado) && estado !== 'CANCELACION_SOLICITADA' && AVISOS_PAGO.includes(estadoPago)
           && String(r.aviso_pago_estado ?? '').trim().toUpperCase() !== estadoPago) accion = 'aviso_pago';
  else if (estado === 'CONFIRMADA' && !pagoPendiente) {
    const f = parseFecha(r.fecha_cita), h = parseHora(r.hora_cita);
    if (f && h) {
      cita = f.set({ hour: h.hour, minute: h.minute });
      if (cita < ahora) {
        // US-7: la cita ya pasó. Nunca se confirma ni se recuerda una cita pasada; al día siguiente se cierra.
        if (cita.plus({ days: 1 }) < ahora && cierres < MAX_CIERRES) { accion = 'cerrar'; cierres++; }
      }
      else if (!si(r.confirmacion_enviada)) accion = 'confirmar_estudiante';
      else if (!si(r.recordatorio_enviado) && cita.diff(ahora, 'hours').hours <= HORAS_RECORDATORIO) accion = 'recordatorio';
    }
  }
  if (!accion) continue;
  let horarioBloqueado = '';
  if (accion === 'aviso_bloqueo') {
    const fb = parseFecha(estado === 'CONFIRMADA' ? r.fecha_cita : r.fecha_solicitada), hb = parseHora(estado === 'CONFIRMADA' ? r.hora_cita : r.hora_solicitada);
    if (fb && hb) horarioBloqueado = fb.set({ hour: hb.hour, minute: hb.minute }).setLocale('es').toFormat("cccc d 'de' LLLL 'a las' h:mm a");
  }
  const telefono = String(r.telefono ?? '').replace(/\D/g, '');
  out.push({ json: {
    ...r, accion, telefono,
    destino: String(r.whatsapp_jid ?? '').trim() || telefono,
    primer_nombre: String(r.nombre ?? '').trim().split(/\s+/)[0] || '',
    profesional: profesionalDe(r),
    estado_pago: estadoPago,
    estado_anterior: estado,
    motivo_estado: String(r.motivo_estado ?? '').trim(),
    fecha_estado_nueva: ahora.toFormat('yyyy-MM-dd HH:mm'),
    cita_texto: cita ? cita.setLocale('es').toFormat("cccc d 'de' LLLL 'a las' h:mm a") : '',
    enlace_calendario: cita ? enlaceCalendario(r, cita) : '',
    horario_bloqueado: horarioBloqueado,
  }});
}
return out;

