// US-7: vuelve a mirar la hoja justo antes de cerrar, por si alguien cambió el estado
// mientras el motor trabajaba. Solo cierra las que SIGUEN en CONFIRMADA.
const candidatas = new Set($('Clasificar acciones').all().filter(x => x.json.accion === 'cerrar').map(x => String(x.json.id)));
const ahora = DateTime.now().setZone('America/Bogota').toFormat('yyyy-MM-dd HH:mm');
return $input.all()
  .filter(i => candidatas.has(String(i.json.id)) && String(i.json.estado ?? '').trim().toUpperCase() === 'CONFIRMADA')
  .map(i => ({ json: { id: i.json.id, fecha_estado_nueva: ahora } }));
